diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..7854a1d 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,56 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+const LINEAS_RF006 = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("RF-006-a: descuento global del 10 % recalcula total, IVA y neto", () => {
+  assert.deepEqual(calcularFactura(LINEAS_RF006, { descuentoGlobal: 10 }), {
+    totalCentavos: 9945,
+    ivaCentavos: 1293,
+    netoCentavos: 8652,
+  });
+});
+
+test("RF-006-b: sin descuento todo queda igual que RF-002", () => {
+  const esperado = { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 };
+  assert.deepEqual(calcularFactura(LINEAS_RF006), esperado);
+  assert.deepEqual(calcularFactura(LINEAS_RF006, {}), esperado);
+  assert.deepEqual(calcularFactura(LINEAS_RF006, { descuentoGlobal: 0 }), esperado);
+});
+
+test("RF-006-c: descuento del 100 % deja todo en cero", () => {
+  assert.deepEqual(calcularFactura(LINEAS_RF006, { descuentoGlobal: 100 }), {
+    totalCentavos: 0,
+    ivaCentavos: 0,
+    netoCentavos: 0,
+  });
+});
+
+test("RF-006-d: el descuento se redondea al centavo con Math.round", () => {
+  const r = calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 99 }], { descuentoGlobal: 50 });
+  assert.equal(r.totalCentavos, 50);
+});
+
+test("RF-006-e: descuento fuera de 0–100 se rechaza", () => {
+  assert.throws(() => calcularFactura(LINEAS_RF006, { descuentoGlobal: -1 }), RangeError);
+  assert.throws(() => calcularFactura(LINEAS_RF006, { descuentoGlobal: 101 }), RangeError);
+});
+
+test("RF-006-f: descuento no entero se rechaza (ADR-001)", () => {
+  for (const d of [10.5, "10", NaN, null]) {
+    assert.throws(() => calcularFactura(LINEAS_RF006, { descuentoGlobal: d }), RangeError);
+  }
+});
+
+test("RF-006-g: emitirFactura no cambia: congelada y sin descuento", () => {
+  const f = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items: LINEAS_RF006 });
+  assert.ok(Object.isFrozen(f));
+  assert.equal(f.totalCentavos, 11050);
+});
